source='''from collections import Counter, defaultdict

def transform(grid):
    rows, cols = len(grid), len(grid[0])
    best = None
    best_counts = None
    for p in range(2, min(11, rows + cols)):
        counts = defaultdict(Counter)
        for r, row in enumerate(grid):
            for c, value in enumerate(row):
                if r >= 3 and c >= 3 and value != 0:
                    counts[(r + c) % p][value] += 1
        total = sum(sum(v.values()) for v in counts.values())
        score = sum(max(v.values()) for v in counts.values())
        candidate = (score, -p)
        if best is None or candidate > best:
            best, best_counts = candidate, counts
    p = -best[1]
    palette = {phase: counts.most_common(1)[0][0] for phase, counts in best_counts.items()}
    out = [row[:] for row in grid]
    for r in range(rows):
        for c in range(cols):
            if out[r][c] != 0:
                continue
            if r == 0 or r == 1:
                out[r][c] = 1
            elif r == 2 and c >= 2:
                out[r][c] = 4
            elif c < 3:
                out[r][c] = (1, 1, 4)[c]
            else:
                out[r][c] = palette[(r + c) % p]
    return out
'''
